WITH ranked AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level FROM employees QUALIFY ROW_NUMBER() OVER (PARTITION BY level ORDER BY salary, id) = 1), enriched AS (SELECT s.id, s.email, s.dept_id, s.manager_id, s.job_title, s.hire_date, s.is_remote, d.location, d.budget FROM ranked s LEFT JOIN departments d ON s.dept_id = d.id), deduped AS (SELECT * FROM enriched QUALIFY ROW_NUMBER() OVER (PARTITION BY location, job_title ORDER BY budget DESC NULLS FIRST, id) = 1), with_dims AS (SELECT a.id, a.email, a.dept_id, a.manager_id, a.job_title, a.location, e.hire_date AS employee_hire_date FROM deduped a LEFT JOIN employees e ON a.manager_id = e.id WHERE e.dept_id = 26) SELECT manager_id, DATE_TRUNC('QUARTER', employee_hire_date) AS quarter_start, location, COUNT_IF(job_title = 'Intern') AS intern_events, COUNT(*) FILTER (WHERE job_title = 'Analyst') AS analyst_rows, SORT_ARRAY(COLLECT_SET(location)) AS location_list, COUNT(CASE WHEN location = 'New York' THEN 1 END) AS new_york_count, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2 FROM with_dims GROUP BY manager_id, DATE_TRUNC('QUARTER', employee_hire_date), location HAVING COUNT(DISTINCT id) > 1 ORDER BY new_york_count
